// web/src/components/firebase-messaging-sw.js (generated by vite.config.js)
// Service worker FCM: menerima notifikasi saat aplikasi tertutup / di latar belakang.
// WAJIB berada di akar situs (https://domain-anda/firebase-messaging-sw.js).
//
// Konfigurasi Firebase publik diinjeksi saat Vite melayani atau membangun aplikasi.
/* global importScripts, firebase, self, clients */
importScripts('https://www.gstatic.com/firebasejs/11.10.0/firebase-app-compat.js');
importScripts('https://www.gstatic.com/firebasejs/11.10.0/firebase-messaging-compat.js');

firebase.initializeApp(__FIREBASE_CONFIG__);

const messaging = firebase.messaging();

// Payload yang memuat blok "notification" ditampilkan otomatis oleh SDK.
// Handler ini hanya untuk pesan "data-only".
messaging.onBackgroundMessage((payload) => {
  if (payload.notification) return;
  const d = payload.data || {};
  if (!d.title) return;
  self.registration.showNotification(d.title, {
    body: d.body || '',
    icon: d.icon || '/logo-ale.png',
    data: { url: d.url || '/' },
  });
});

// Ketuk notifikasi → fokuskan tab yang ada, atau buka yang baru.
self.addEventListener('notificationclick', (event) => {
  event.notification.close();
  const url = new URL((event.notification.data && event.notification.data.url) || '/', self.location.origin).href;
  event.waitUntil(
    clients.matchAll({ type: 'window', includeUncontrolled: true }).then((daftar) => {
      const ada = daftar.find((c) => c.url.startsWith(self.location.origin));
      if (ada) return ada.focus().then((c) => (c && 'navigate' in c ? c.navigate(url) : undefined));
      return clients.openWindow(url);
    }),
  );
});
